pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a + b);
        vm.assume(a > 0 || b > 0);
        address owner0;
        try c.owner() returns (address __r) { owner0 = __r; } catch { return; }
        try c.go{value: a}() {} catch { return; }
        uint balAfterA = address(c).balance;
        try c.go{value: b}() {} catch { return; }
        uint balAfterB = address(c).balance;
        assertTrue(c.owner() == owner0 && balAfterA == 0 && balAfterB == 0);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
}
